use ark_bn254::Fr as A;use ark_ff::{AdditiveGroup,Field,FftField,PrimeField,BigInteger};use zopro_bn254::Fr as Z;use zopro_core::fft::Plan;
fn za(x:A)->Z{Z::from_le_bytes_mod_order(&x.into_bigint().to_bytes_le())}
fn az(x:Z)->A{A::from_le_bytes_mod_order(&x.to_canonical().into_iter().flat_map(u64::to_le_bytes).collect::<Vec<_>>())}
fn eval(n:usize,r:A,c:A,t:&[(usize,A)])->Vec<A>{let mut out=vec![A::ZERO;n];for &(k,v)in t{let step=r.pow([k as u64]);let mut a=v*c.pow([k as u64]);for out in &mut out{*out+=a;a*=step;}}out}
fn compare(got:Vec<Z>,want:&[A]){assert_eq!(got.len(),want.len());for(i,(x,&y))in got.into_iter().zip(want).enumerate(){assert_eq!(az(x),y,"index={i}");}}
fn main(){let workers:usize=std::env::var("RAYON_NUM_THREADS").unwrap().parse().unwrap();let twisted=std::env::var("ZOPRO_CPU_TWISTED_FFT").unwrap()=="1";let zero=std::env::var("ZOPRO_CPU_PREPARE_MAX_BYTES").as_deref()==Ok("0");let mut compared=0;
rayon::ThreadPoolBuilder::new().num_threads(workers).stack_size(512*1024).build().unwrap().install(||{for round in 0..2{let n=262144;let r=A::get_root_of_unity(n as u64).unwrap().pow([3]);let c=A::from(11u64);let mut p=Plan::new(n,za(r),za(c),za((c.pow([n as u64])-A::ONE).inverse().unwrap()));let before=p.study_configuration();assert_eq!(before.1,twisted&&!zero);p.prepare_euler_study();let after=p.study_configuration();assert!(!after.1);assert_eq!((after.2,after.3),if zero{(0,0)}else if twisted{(16,0)}else{(0,16)},"column admission must match old OFF");
let seed=401+workers as u64+round;let ta=[(0,A::from(seed)),(5,A::from(43u64)),(n/2+7,-A::ONE),(n-1,A::from(seed+47))];let tb=[(1,-A::ONE),(n/3+2,A::from(seed+53)),(n-2,A::from(59u64))];let a=eval(n,r,A::ONE,&ta);let b=eval(n,r,A::ONE,&tb);let da=eval(n,r,A::ONE,&ta.map(|(k,a)|(k,a*A::from(k as u64))));let db=eval(n,r,A::ONE,&tb.map(|(k,a)|(k,a*A::from(k as u64))));let input=|v:&[A]|v.iter().copied().map(za).collect::<Vec<_>>();compare(p.euler_product_study(input(&a),input(&b)),&(0..n).map(|i|A::from(n as u64)*(da[i]*b[i]+db[i]*a[i])).collect::<Vec<_>>());let ac=eval(n,r,c,&ta);let bc=eval(n,r,c,&tb);compare(p.current_product_study(input(&a),input(&b)),&(0..n).map(|i|ac[i]*bc[i]).collect::<Vec<_>>());compared+=2*n;println!("ADMISSION_FIXED workers={workers} twisted={twisted} zero={zero} round={round} before={before:?} after={after:?}");drop(p);}});assert_eq!(compared,1048576);println!("ADMISSION_FIXED_OUTPUTS={compared}");}
